<script>
(() => {
  'use strict';
  const NS = 'wyxy';
  const PROTOCOL_VERSION = 1;
  const GIRLS = {
    linwanqiu: '林晚秋', jiangling: '江铃', sunian: '苏念',
    fangtangtang: '方糖糖', guyunlei: '顾云蕾',
  };
  const app = document.getElementById('wyxy-app');
  const $$ = sel => app.querySelector(`[data-bind="$${sel}"]`);
  const setView = v => { app.dataset.view = v; };
  const uid = () => (crypto.randomUUID ? crypto.randomUUID() : 'id-' + Math.random().toString(36).slice(2));

  // ---- 依赖探测（契约 §4.7）----
  const hasTH = () => typeof window.getLastMessageId === 'function' && typeof window.createChatMessages === 'function';
  const hasMvu = () => typeof window.Mvu === 'object' && window.Mvu && typeof window.Mvu.getMvuData === 'function';

  // ---- GameStateAdapter：只读快照（契约 §4.4，组件不直接摸楼层 API）----
  const adapter = {
    lastError: null,
    snapshot() {
      try {
        const lastId = window.getLastMessageId();
        let stat = null;
        try {
          const mvu = window.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
          if (mvu && mvu.stat_data && mvu.stat_data.world) stat = mvu.stat_data;
        } catch (e) { /* 楼层无帧则回退 chat 域 */ }
        if (!stat) {
          try {
            const mvu = window.Mvu.getMvuData({ type: 'chat' });
            if (mvu && mvu.stat_data && mvu.stat_data.world) stat = mvu.stat_data;
          } catch (e) { /* 保持 null */ }
        }
        let story = '';
        if (lastId > 0) {
          const msgs = window.getChatMessages(lastId);
          if (msgs && msgs[0] && msgs[0].role === 'assistant') story = stripSystem(msgs[0].message);
          else if (lastId > 1) {
            const prev = window.getChatMessages(lastId - 1);
            if (prev && prev[0] && prev[0].role === 'assistant') story = stripSystem(prev[0].message);
          }
        }
        return { lastId, stat, story };
      } catch (e) {
        this.lastError = e;
        return null;
      }
    },
  };
  const stripSystem = t => String(t || '')
    .replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, '')
    .replace(/<结算[^>]*\/>/g, '')
    .replace(/<(?:UpdateVariable|结算)[^]*$$/, '')
    .trim();

  // ---- chat-service：全部楼层写操作收口（契约 §4.1）----
  const chatService = {
    async sendAction(text, meta) {
      await window.createChatMessages(
        [{ role: 'user', message: text, data: { same_floor_ui: { protocol_version: PROTOCOL_VERSION, ...meta } } }],
        { refresh: 'affected' },
      );
      await window.triggerSlash('/trigger');
    },
  };

  // ---- 可恢复 UI 状态：开局草稿存 chat 域 same_floor_ui（契约 §4.4）----
  const draftStore = {
    async save(draft) {
      try {
        await window.insertOrAssignVariables(
          { same_floor_ui: { protocol_version: PROTOCOL_VERSION, wizard_draft: draft } },
          { type: 'chat' },
        );
      } catch (e) { /* 草稿非关键路径 */ }
    },
    load() {
      try {
        const v = window.getVariables({ type: 'chat' });
        const d = v && v.same_floor_ui && v.same_floor_ui.wizard_draft;
        return d && typeof d === 'object' ? d : null;
      } catch (e) { return null; }
    },
  };

  // ---- busy 链（契约 §4.2：事件+超时对账）----
  let busyTimer = null;
  function setBusy(on, text) {
    app.dataset.busy = on ? '1' : '';
    if (text) $$('busy-text').textContent = text;
    clearTimeout(busyTimer);
    if (on) busyTimer = setTimeout(() => { setBusy(false); showError('main-error', '生成超时或事件漏收，已按当前楼层对账。'); refresh(); }, 120000);
  }
  function showError(slot, msg) {
    const el = $$(slot);
    if (!el) return;
    el.textContent = msg || '';
    el.dataset.show = msg ? '1' : '';
  }

  // ---- 渲染 ----
  const STAGE_LABEL = k => (k >= 4 ? '蜕变' : k >= 2 ? '敞开' : k >= 1 ? '试探' : '抵触');
  const AP_ACTS = ['talk', 'accompany', 'group', 'drill', 'confine', 'electro', 'paperwork'];
  function renderMain(snap) {
    const s = snap.stat;
    if (s && s.world) {
      $$('day').textContent = s.world.day;
      $$('ap').textContent = s.world.ap;
      $$('pressure').textContent = s.world.parent_pressure;
      $$('pressure-bar').style.width = Math.max(0, Math.min(100, +s.world.parent_pressure || 0)) + '%';
      const ended = !!s.world.总结局;
      const apEmpty = s.world.ap <= 0;
      const electroLocked = (+s.world.parent_pressure || 0) < 60;
      for (const act of AP_ACTS) {
        const b = app.querySelector(`[data-act="$${act}"]`);
        b.disabled = ended || apEmpty || (act === 'electro' && electroLocked);
      }
      app.querySelector('[data-act="endday"]').disabled = ended;
      app.querySelector('[data-act="electro"]').title = electroLocked ? '未解锁：家长压力 ≥60 时可用' : '';
      $$('ending-banner').dataset.show = ended ? '1' : '';
      if (ended) $$('ending-banner').textContent = `修正期已结束——园长线总结局：$${s.world.总结局}`;
      $$('hint').textContent = ended ? '' : apEmpty ? '行动点已耗尽——结束今天，进入夜晚。' : '';
      renderGirls(s);
    } else {
      $$('hint').textContent = '（变量尚未初始化——等待第一轮生成完成）';
    }
    $$('story').textContent = snap.story || '';
  }

  function renderGirls(s) {
    const wrap = $$('girl-cards');
    wrap.textContent = '';
    for (const [key, name] of Object.entries(GIRLS)) {
      const g = s.girls && s.girls[key];
      if (!g) continue;
      const card = document.createElement('button');
      card.type = 'button';
      card.className = 'wy-gcard';
      const h = document.createElement('h3');
      h.append(name);
      const stage = document.createElement('span');
      stage.className = 'wy-stage';
      stage.textContent = g.结局 ? '' : STAGE_LABEL(g.心结 | 0);
      h.appendChild(stage);
      card.appendChild(h);
      for (const [label, field, cls] of [['修正', '修正值', ''], ['信任', '信任', 'trust']]) {
        const row = document.createElement('div');
        row.className = 'wy-row';
        const bar = document.createElement('span');
        bar.className = 'wy-bar ' + cls;
        const fill = document.createElement('i');
        fill.style.width = Math.max(0, Math.min(100, +g[field] || 0)) + '%';
        bar.appendChild(fill);
        row.append(label, bar, String(g[field]));
        card.appendChild(row);
      }
      // 创伤默认弱化：只给小图标暗示，详情才见数值（契约 §4.3）
      const foot = document.createElement('div');
      foot.className = 'wy-row';
      if ((g.创伤 | 0) > 0 && !g.结局) {
        const flag = document.createElement('span');
        flag.className = 'wy-flag';
        flag.textContent = '⚠ 状态记录';
        foot.appendChild(flag);
      }
      if (g.结局) {
        const end = document.createElement('span');
        end.className = 'wy-ended';
        end.textContent = '结局：' + g.结局;
        foot.appendChild(end);
      }
      card.appendChild(foot);
      card.addEventListener('click', () => openGirlDetail(key, name, g));
      wrap.appendChild(card);
    }
  }

  function openGirlDetail(key, name, g) {
    $$('detail-title').textContent = name + ' · 详细档案';
    $$('detail-body').textContent =
      `阶段：$${g.结局 ? '——' : STAGE_LABEL(g.心结 | 0)}（心结 $${g.心结}/4）\n` +
      `修正值：$${g.修正值}　信任：$${g.信任}\n` +
      `创伤：$${g.创伤}　（机构报表上没有这一栏）\n` +
      `状态：$${g.状态}$${g.标记 && g.标记.电疗过 ? '\n记录：接受过「物理疗法」（不可逆）' : ''}` +
      `$${g.标记 && g.标记.秘密揭示 ? '\n她把最重要的事告诉了你。' : ''}` +
      `$${g.结局 ? '\n结局：' + g.结局 : ''}`;
    $$('girl-detail').showModal();
  }

  function renderReview(snap) {
    const wrap = $$('review-list');
    wrap.textContent = '';
    try {
      for (let i = 1; i <= snap.lastId; i++) {
        const msgs = window.getChatMessages(i);
        const m = msgs && msgs[0];
        if (!m) continue;
        const item = document.createElement('div');
        item.className = 'wy-rmes';
