// 网瘾学园 bridge（生成物，勿手改；源：src/）
// stat_data 结构与默认值 —— 唯一事实来源：设计契约 §3 账本
// 本文件是账本的可执行投影：schema 默认值即「未开局安全态」。

const SCHEMA_VERSION = 1;

const GIRL_KEYS = ['linwanqiu', 'jiangling', 'sunian', 'fangtangtang', 'guyunlei'];

const GIRL_NAMES = {
  linwanqiu: '林晚秋',
  jiangling: '江铃',
